                blob = "\n\n".join(
                    f"### `{', '.join(targets_of(f))}`\n{f['reason']}\n\n"
                    f"Your test:\n```python\n{f['test']}\n```\n\n"
                    f"What happened:\n```\n{f['output'][-700:]}\n```"
                    for f in pedaco
                )
